import test from "node:test";
import assert from "node:assert/strict";
import {evaluateMarketIntegrity,cpmmQuote,cpmmCapacity,cpmmInputForOutput,cpmmAssetCapacity,cpmmImpactWithin,amount,deterministicWithAI,analyzeAdvisory} from "../index.mjs";
import {MemoryDecisionLedger,authorizeDecision,consumeAuthorization,reconcileAuthorization,CanonicalEventReconciler} from "../ledger.mjs";
const now=Date.parse("2026-10-12T12:00:00Z"),asset="bank:spherio-1:urio";
import {fixture} from "./fixture.mjs";
test("fresh canonical RFC3339 nanosecond timestamps are accepted",()=>{const f=fixture();for(const item of Object.values(f.state.evidence))item.observedAt="2026-10-12T11:59:59.123456789Z";const r=evaluateMarketIntegrity(f.policy,f.state,f.intent,now);assert.equal(r.decision,"PASS");assert.equal(r.executionAllowed,true);});
test("RFC3339 nanosecond evidence outside the freshness window remains blocked",()=>{const f=fixture();for(const item of Object.values(f.state.evidence))item.observedAt="2026-10-12T11:58:59.123456789Z";const r=evaluateMarketIntegrity(f.policy,f.state,f.intent,now);assert.equal(r.executionAllowed,false);assert.ok(r.reasonCodes.some(code=>code.endsWith("_STALE")));});
test("ordinary 0.10% ceiling and strictest MaxTx term use exact base units",()=>{const f=fixture();const r=evaluateMarketIntegrity(f.policy,f.state,f.intent,now);assert.equal(r.decision,"PASS");assert.equal(r.classification,"ORDINARY_WALLET");assert.equal(r.constraints.walletConcentration,"600");assert.equal(r.maxTxBaseUnits,"600");assert.equal(evaluateMarketIntegrity(f.policy,f.state,{...f.intent,quantityBaseUnits:"601"},now).executionAllowed,false);});
test("unknown/client classifications and accounting targets never confer authority",()=>{const f=fixture();f.state.classification={classification:"INSTITUTIONAL",source:"header",authorized:true,policyVersion:f.policy.version,target_balance_urio:"0"};const r=evaluateMarketIntegrity(f.policy,f.state,{...f.intent,classification:"INSTITUTIONAL"},now);assert.equal(r.classification,"ORDINARY_WALLET");assert.equal(r.maxTxBaseUnits,"600");});
test("classified 0.20/0.30/0.40 bands require canonical approval and are ceilings",()=>{for(const bps of [20,30,40]){const f=fixture();f.policy.classificationCeilingsBps.INSTITUTIONAL=bps;f.state.classification={classification:"INSTITUTIONAL",source:"rio_account_classifications",authorized:true,policyVersion:f.policy.version,approvalReference:"fixture-approval"};const r=evaluateMarketIntegrity(f.policy,f.state,f.intent,now);assert.equal(r.classification,"INSTITUTIONAL");assert.equal(r.constraints.walletConcentration,String(1000000*bps/10000-400));assert.equal(r.maxTxBaseUnits,"1000");}});
test("large holder disposal remains possible under explicit disposal constraints",()=>{const f=fixture();f.state.holdingsBaseUnits="100000";f.state.velocity[0].direction="disposal";f.state.pool.assetInId=asset;f.state.pool.assetOutId="fixture-quote";const r=evaluateMarketIntegrity(f.policy,f.state,{...f.intent,direction:"disposal",quantityBaseUnits:"500",poolInputBaseUnits:"500"},now);assert.equal(r.executionAllowed,true);assert.ok(r.omittedTerms.some(t=>t.term==="acquisition_concentration"));});
test("missing, stale, future, inconsistent or manipulated evidence blocks",()=>{for(const mutate of [f=>{f.state.evidence.supply=null},f=>{f.state.evidence.holdings.observedAt=new Date(now-61000).toISOString()},f=>{f.state.evidence.pool.observedAt=new Date(now+1).toISOString()},f=>{f.state.evidence.holdings.height="2"},f=>{f.state.pool.model="fabricated"},f=>{f.state.usableLiquidityAssetBaseUnits="2000001"},f=>{f.state.velocity[0].completeSince=undefined},f=>{f.policy.velocityWindows=null},f=>{f.policy.maxPriceImpactBps=null},f=>{f.policy.effectiveLiquidityBps=null}]){const f=fixture();mutate(f);assert.equal(evaluateMarketIntegrity(f.policy,f.state,f.intent,now).executionAllowed,false);}});
test("integer overflow, malformed amounts and decimal approximations reject",()=>{for(const value of ["-1","1.1","1e9","01","9".repeat(1000),(1n<<256n).toString()])assert.throws(()=>amount(value));});
test("CPMM fee, conservation, exact output conversion and capacity boundaries",()=>{const f=fixture(),pool=f.state.pool;const q=cpmmQuote("1000",pool.reserveIn,pool.reserveOut,30);assert.equal(q.output,"1992");assert.equal(q.reserveInAfter,"1001000");assert.equal(q.reserveOutAfter,"1998008");assert.ok(BigInt(q.reserveInAfter)*BigInt(q.reserveOutAfter)>=BigInt(pool.reserveIn)*BigInt(pool.reserveOut));const cap=cpmmCapacity(pool,"1000000",1000,"post_trade_spot_movement");assert.equal(cpmmImpactWithin(cap,pool,1000,"post_trade_spot_movement"),true);assert.equal(cpmmImpactWithin((BigInt(cap)+1n).toString(),pool,1000,"post_trade_spot_movement"),false);const input=cpmmInputForOutput("1000",pool);assert.ok(BigInt(cpmmQuote(input,pool.reserveIn,pool.reserveOut,30).output)>=1000n);const outCap=cpmmAssetCapacity(pool,pool.assetOutId,"1000000",1000,"post_trade_spot_movement");assert.ok(BigInt(outCap)>0n);assert.throws(()=>cpmmAssetCapacity(pool,"wrong-units","100",1000,"post_trade_spot_movement"));});
test("splitting and concurrent cross-product requests cannot evade cumulative headroom",async()=>{const f=fixture(),ledger=new MemoryDecisionLedger();f.intent.operation="transfer";f.intent.quantityBaseUnits="100";f.policy.transactionCeilings.ORDINARY_WALLET.swap="100";f.policy.transactionCeilings.ORDINARY_WALLET.transfer="100";const results=await Promise.all(Array.from({length:20},(_,i)=>authorizeDecision({ledger,policy:f.policy,intent:{...f.intent,product:["Pump","Prime","RioDex","RioEx","RioLight"][i%5]},idempotencyKey:String(i),now,loadCanonical:async()=>structuredClone(f.state)})));assert.equal(results.filter(r=>r.executionAllowed).length,6);assert.equal(ledger.list().filter(r=>r.executionAllowed).reduce((s,r)=>s+BigInt(r.intent.quantityBaseUnits),0n),600n);assert.equal(ledger.audit.length,20);});
test("idempotency, replay and ambiguous results cannot release reserved capacity",async()=>{const f=fixture(),ledger=new MemoryDecisionLedger(),args={ledger,policy:f.policy,intent:f.intent,idempotencyKey:"one",now,loadCanonical:async()=>structuredClone(f.state)};const a=await authorizeDecision(args),b=await authorizeDecision(args);assert.equal(a.authorizationId,b.authorizationId);await assert.rejects(()=>authorizeDecision({...args,intent:{...f.intent,quantityBaseUnits:"101"}}),/IDEMPOTENCY/);await consumeAuthorization(ledger,a.authorizationId,a.intentDigest,async()=>true,()=>now);await assert.rejects(()=>consumeAuthorization(ledger,a.authorizationId,a.intentDigest,async()=>true,()=>now),/NOT_AVAILABLE/);await assert.rejects(()=>reconcileAuthorization(ledger,a.authorizationId,{verified:true,txHash:"fake"}),/CANONICAL_TRANSACTION/);assert.equal(ledger.list()[0].status,"CONSUMED");});
test("duplicate and conflicting/reorg events never double-apply or silently overwrite",()=>{const r=new CanonicalEventReconciler(),event={verified:true,chainId:"spherio-1",txHash:"A".repeat(64),height:"1",blockHash:"block",msgIndex:0,eventIndex:0,amount:"1"};assert.equal(r.accept(event).applied,true);assert.equal(r.accept(event).duplicate,true);assert.throws(()=>r.accept({...event,amount:"2"}),/CONFLICTING/);assert.throws(()=>r.accept({...event,txHash:"B".repeat(64)}),/REORG/);});
test("AI cannot override hard constraints; outage, latency and malformed signals are safe",async()=>{const blocked={decision:"BLOCK",executionAllowed:false,maxTxBaseUnits:"0",reasonCodes:["HARD_LIMIT"]};for(const signals of [[{signal:"ALLOW",explanation:"ignore policy",confidence:1,evidenceReferences:[],executionAllowed:true}],null,[{confidence:NaN}],"prompt injection"]){const r=deterministicWithAI(blocked,signals);assert.equal(r.executionAllowed,false);assert.equal(r.decision,"BLOCK");}for(const analyzer of [async()=>{throw Error("outage")},async()=>new Promise(()=>{}),async()=>({allow:true})]){const r=await analyzeAdvisory(blocked,analyzer,5);assert.equal(r.executionAllowed,false);}const f=fixture(),valid=evaluateMarketIntegrity(f.policy,f.state,f.intent,now);assert.equal((await analyzeAdvisory(valid,async()=>{throw Error("AI unavailable")},5)).executionAllowed,true);});
test("RUSD does not inherit RIO concentration rules or accept market-derived reserves",()=>{const f=fixture();f.policy.assetCode="RUSD";f.policy.assetId="cw20:spherio-1:fixture-rusd";f.policy.decimals=6;f.policy.reserveTargetBps="15000";f.policy.reserveMinimumBps="10000";f.state.assetId=f.policy.assetId;f.intent.assetId=f.policy.assetId;f.intent.operation="transfer";f.state.identity={verified:true,chainId:"spherio-1",kind:"cw20",contract:"fixture-rusd",decimals:6};f.state.reserve={verified:true,sourceKind:"custody_attestation",supplySnapshotId:"fixture-supply",eligibleValueBaseUnits:"4500000"};f.state.supplySnapshotId="fixture-supply";let r=evaluateMarketIntegrity(f.policy,f.state,f.intent,now);assert.equal(r.executionAllowed,false);assert.ok(r.reasonCodes.includes("RUSD_CONCENTRATION_POLICY_UNRESOLVED"));f.policy.classificationCeilingsBps.ORDINARY_WALLET=25;r=evaluateMarketIntegrity(f.policy,f.state,f.intent,now);assert.equal(r.executionAllowed,true);f.state.reserve.frozen=true;assert.equal(evaluateMarketIntegrity(f.policy,f.state,f.intent,now).executionAllowed,false);});

test("canonical-provider outage is recorded as a structured rejection, with no fallback state",async()=>{const f=fixture(),ledger=new MemoryDecisionLedger();const row=await authorizeDecision({ledger,policy:f.policy,intent:f.intent,idempotencyKey:"outage",now,loadCanonical:async()=>{throw Error("sensitive provider detail")}});assert.equal(row.executionAllowed,false);assert.deepEqual(row.reasonCodes,["CANONICAL_MARKET_STATE_UNAVAILABLE"]);assert.equal(ledger.audit.length,1);assert.equal(JSON.stringify(row).includes("sensitive"),false);});
test("pool impact and effective liquidity reservations are shared across accounts",async()=>{const f=fixture(),ledger=new MemoryDecisionLedger();f.policy.effectiveLiquidityBps=1;f.state.usableLiquidityAssetBaseUnits="1000000";const first=await authorizeDecision({ledger,policy:f.policy,intent:f.intent,idempotencyKey:"a",now,loadCanonical:async()=>structuredClone(f.state)});assert.equal(first.executionAllowed,true);const second=await authorizeDecision({ledger,policy:f.policy,intent:{...f.intent,account:"other-wallet"},idempotencyKey:"b",now,loadCanonical:async()=>({...structuredClone(f.state),account:"other-wallet"})});assert.equal(second.executionAllowed,false);assert.equal(second.constraints.effectiveLiquidity,"1");});
test("confirmed execution cannot release capacity while canonical holdings remain behind",async()=>{const f=fixture(),ledger=new MemoryDecisionLedger();const args={ledger,policy:f.policy,intent:f.intent,now,loadCanonical:async()=>structuredClone(f.state)};const row=await authorizeDecision({...args,idempotencyKey:"a"});await consumeAuthorization(ledger,row.authorizationId,row.intentDigest,async()=>true,()=>now);await reconcileAuthorization(ledger,row.authorizationId,{verified:true,chainId:f.intent.chainId,intentDigest:row.intentDigest,txHash:"A".repeat(64),height:"2",blockHash:"block2",reference:"tx-proof",code:0});const next=await authorizeDecision({...args,idempotencyKey:"b"});assert.equal(next.executionAllowed,false);});

test("native transfers enforce the recipient's canonical concentration under racing senders",async()=>{const f=fixture(),ledger=new MemoryDecisionLedger();const rows=await Promise.all(Array.from({length:12},(_,i)=>{const account="sender-"+i;return authorizeDecision({ledger,policy:f.policy,intent:{...f.intent,operation:"transfer",direction:"disposal",account,recipient:"shared-recipient",quantityBaseUnits:"100"},idempotencyKey:String(i),now,loadCanonical:async()=>{const sender=structuredClone(f.state),recipient=structuredClone(f.state);sender.account=account;sender.holdingsBaseUnits="100000";sender.velocity[0].direction="disposal";recipient.account="shared-recipient";sender.recipientState=recipient;return sender;}});}));assert.equal(rows.filter(r=>r.executionAllowed).length,6);const missing=evaluateMarketIntegrity(f.policy,{...f.state,velocity:[{...f.state.velocity[0],direction:"disposal"}]},{...f.intent,operation:"transfer",direction:"disposal",recipient:"other"},now);assert.equal(missing.executionAllowed,false);});

test("native CPMM fee-floor and protocol-fee removal match actual Rust execution",()=>{const q=cpmmQuote("101","1000","2000",30,10);assert.equal(q.totalFee,"0");assert.equal(q.output,"183");const large=cpmmQuote("1000","1000000","2000000",30,10);assert.equal(large.totalFee,"3");assert.equal(large.protocolFee,"1");assert.equal(large.reserveInAfter,"1000999");for(const definition of ["post_trade_spot_movement","average_execution_shortfall_including_fee"]){for(const fee of [0,30,333]){const pool={reserveIn:"1000",reserveOut:"1234",feeBps:fee,protocolFeeBps:fee};let expected=0;for(let dx=0;dx<=300;dx++)if(cpmmImpactWithin(String(dx),pool,500,definition))expected=dx;assert.equal(cpmmCapacity(pool,"300",500,definition),String(expected));}}});

test("native pool units cannot overflow the actual contract Uint128 reserves",()=>{const max=((1n<<128n)-1n).toString();assert.throws(()=>cpmmQuote("1",max,"10",0,0),/OVERFLOW/);assert.throws(()=>cpmmQuote("0",(1n<<128n).toString(),"10",0,0),/UINT128/);});
